/bin/zsh -lc "node - <<'NODE'
const { parseEnv } = require('node:util');
for (const [name, text] of [
  ['bom', '\\ufeffGEMINI_API_KEY=value\\n'],
  ['crlf', 'GEMINI_API_KEY=value\\r\\n'],
  ['spaces', ' GEMINI_API_KEY = value \\n'],
  ['export', 'export GEMINI_API_KEY=value\\n'],
]) {
  const parsed = parseEnv(text);
  console.log(name, Object.keys(parsed), Boolean(parsed.GEMINI_API_KEY));
}
NODE"

